    NV_DATA_S(_y)[SP_syn_CD8_C1_PD1] = _species_var[SP_syn_CD8_C1_PD1];
    // syn_CD8_C1.CD28 = (CD8_CD28_total / A_Tcell) * syn_CD8_C1
